import json
with open('/app/resources/treasury_bulletin_1982_08.json', 'r') as f:
    data = json.load(f)

# Let's look for the auction data
def find_value(d, key):
    if isinstance(d, dict):
        for k, v in d.items():
            if key.lower() in k.lower():
                print(f'Found: {k}: {v}')
            if isinstance(v, (dict, list)):
                find_value(v, key)
    elif isinstance(d, list):
        for item in d:
            find_value(item, key)

# Try to find the section
print('Looking for PDO-6...')
for item in data:
    if isinstance(item, dict):
        for k, v in item.items():
            if 'PDO-6' in str(k) or 'allotment' in str(k).lower():
                print(k, v)
